     "desc": "位于避暑山庄北侧，乾隆年间仿建新疆伊犁固尔札庙而建。庙宇布局严谨，主殿普乐寺气势恢宏，是清政府团结新疆蒙古族的重要历史见证，体现了民族团结的文化内涵。",
     "lat": null,
