     "desc": "位于武当山南岩之巅，始建于元代，是武当山最具特色的宫观之一。宫内有龙头香（延伸出悬崖3米外的石雕龙形香炉），游客需匍匐前行烧香，惊险刺激。宫后有天柱峰绝壁，景色壮观。",
     "lat": null,
