     "desc": "位于武当山五龙岩下，始建于唐代，是武当山最古老的道观之一。宫内建筑依山而建，气势恢宏。历史上曾是武当山道教活动的中心之一，有五龙神祠、雷祖殿等重要建筑。",
     "lat": null,
