     "desc": "位于拉萨西郊根培乌孜山南坡，始建于1416年，是藏传佛教格鲁派六大寺庙中规模最大的一座。寺内有众多佛殿和扎仓（学院），曾拥有僧侣上万名。寺前的观景台可俯瞰拉萨河谷和拉萨市区。",
