     "name": "苏州街",
     "desc": "位于颐和园后湖两岸，是仿照苏州水乡街市建造的皇家买卖街。乾隆年间始建，光绪年间重建，两岸店铺林立，有茶楼、酒馆、绸缎庄、当铺等，再现了江南水乡的繁华景象。皇帝和后妃们曾在此体验民间购物乐趣。",
