     "desc": "连接昆明湖东岸与南湖岛的大型石拱桥，桥长150米，有十七个桥洞，故名十七孔桥。桥栏柱上雕刻有500多只形态各异的石狮子，其中一对母子狮最为生动。桥两端各有华表一座，桥身弧形优美，是颐和园中最优美的桥梁建筑。",
