     "desc": "位于大足宝顶山脚下，全面展示大足石刻的考古发现和保护成果。馆内陈列有大足石刻的拓片、模型和出土文物，通过多媒体手段生动再现了石刻的开凿历史和艺术价值。博物馆还设有数字展示中心，通过VR技术让游客 virtual 游览不可近距离接触的石窟。",
