     "desc": "位于良渚古城遗址公园内，是一个展示良渚文化时期动物遗存的区域。鹿苑中饲养有梅花鹿等动物，模拟良渚文化时期的生态环境。苑内还有良渚文化时期的陶器、石器和玉器展示，让游客了解良渚人与动物的关系及其在生活中的重要性。",
     "lat": null,
