   "id": "h43",
   "name": "九寨沟风景名胜区",
   "cat": "自然遗产",
   "prov": "四川阿坝",
   "lat": 33.26,
   "lng": 103.92,
   "detail": "九寨沟位于四川省阿坝州九寨沟县，以原始的生态环境和秀丽奇特的自然风光闻名于世。景区由三条沟组成（树正沟、日则沟、则查洼沟），沟内有九个藏族寨子。\"九寨归来不看水\"——这里拥有梯田般的湖泊群（海子）、清澈见底的湖水、多彩的钙华滩流和磅礴的瀑布，构成了如梦似幻的水景王国。",
   "multi": false,
   "spots": [
    {
     "name": "五花海",
     "desc": "九寨沟最绚丽的海子，位于日则沟孔雀河上游。五花海水色斑斓，湖底有钙华沉积和倒木，阳光照射下呈现出鹅黄、墨绿、深蓝、藏青等色彩，被誉为九寨沟最美丽的湖泊。湖面倒映着周围的彩林和雪山，宛如一幅天然油画。",
     "lat": null,
     "lng": null
    },
    {
     "name": "五彩池",
     "desc": "九寨沟最小的海子，却是最鲜艳夺目的湖泊。五彩池面积不大但水色极为丰富，池水呈现出蓝绿、黄橙、粉红等多种色彩，宛如调色盘。池底有钙华沉积和钟乳石，在阳光下闪闪发光，是九寨沟最具代表性的景观。",
     "lat": null,
     "lng": null
    },
    {
     "name": "诺日朗瀑布",
     "desc": "九寨沟最宽阔的瀑布，宽270米，高20米，是中国最宽的钙华瀑布。瀑布从茂密的森林中飞泻而下，水声轰鸣，气势磅礴。秋季时瀑布两侧彩林倒映水中，景色最为壮观。诺日朗在藏语中意为雄伟壮观，名副其实。",
     "lat": null,
     "lng": null
    },
    {
     "name": "珍珠滩瀑布",
     "desc": "九寨沟的标志性瀑布之一，因水流冲击钙华滩面溅起无数水珠如珍珠般滚动而得名。瀑布高21米，宽约80米，水流从滩面上奔腾而下，声震山谷。九寨沟九寨沟瀑布的拍摄地《西游记》片尾曲中唐僧师徒牵马涉水的场景即在此拍摄。",
     "lat": null,
     "lng": null
    },
    {
     "name": "树正群海",
     "desc": "九寨沟树正沟中的一系列海子群，由大小不一的几十个湖泊组成。湖泊之间有狭窄的出水道相连，水流在钙华堤坝上形成层层叠叠的瀑布和滩流。群海周围是茂密的原始森林，倒木立于水中，构成独特的水下森林景观。",
     "lat": null,
     "lng": null
    },
    {
     "name": "芦苇海",
     "desc": "九寨沟树正沟中的一片浅水湖泊，湖面覆盖着茂密的芦苇丛。芦苇在水中随风摇曳，湖水清澈见底，倒映着蓝天白云和远处的雪山。芦苇海是九寨沟最具田园诗意的景点，也是观察水鸟的理想场所。",
     "lat": null,
     "lng": null
    },
    {
     "name": "火花海",
     "desc": "九寨沟日则沟中的一处海子，因水面在阳光照射下闪烁如火花而得名。火花海水色湛蓝，湖中有大量钙华沉积和倒木，水流从湖中溢出形成小型瀑布。傍晚时分夕阳照射湖面，水波闪烁如万点火花，景色尤为迷人。",
     "lat": null,
     "lng": null
    },
    {
     "name": "长海",
     "desc": "九寨沟海拔最高、面积最大的湖泊，位于日则沟尽头，海拔3100米。长海无出水口，湖水来源于雪山融水和降水，水色湛蓝深邃。长海四周被高大的雪山环绕，冬季湖面结冰，景色壮丽。长海是九寨沟海拔最高的观景点之一。",
     "lat": null,
     "lng": null
    },
    {
     "name": "熊猫海",
     "desc": "九寨沟日则沟中的一处海子，因传说中熊猫曾到此嬉戏而得名。熊猫海水色清澈，湖中有大量倒木和钙华沉积，水下世界丰富多彩。海子周围是茂密的原始森林，是观察大熊猫等珍稀动物的潜在栖息地。",
     "lat": null,
     "lng": null
    },
    {
     "name": "箭竹海",
     "desc": "九寨沟日则沟中的一处海子，因湖畔生长着大量箭竹而得名。箭竹是大熊猫的主要食物，因此这里也是大熊猫活动的常见区域。箭竹海水色清澈，湖面倒映着周围的竹林和雪山，环境幽静优美。",
     "lat": null,
     "lng": null
    },
    {
     "name": "原始森林",
     "desc": "九寨沟核心区的一片原始森林，面积广阔，植被保存完好。森林中有大量的珍稀植物和动物，包括大熊猫、金丝猴、羚牛等国家级保护动物。原始森林中古树参天，苔藓覆盖，充满了原始自然的神秘气息，是体验九寨沟原生态自然的最佳区域。",
     "lat": null,
     "lng": null
    },
    {
     "name": "孔雀河",
     "desc": "九寨沟日则沟中的一段河道，因河道两岸植被丰富、水色斑斓如孔雀羽毛而得名。孔雀河水流清澈，河道蜿蜒曲折，两岸彩林倒映水中，景色如画。孔雀河下游连接五花海，是九寨沟最精华的游览路段之一。",
     "lat": null,
     "lng": null
    },
    {
     "name": "季节海",
     "desc": "九寨沟中随季节变化而呈现不同景观的海子。九寨沟的海子受地下泉水和雪山融水补给，不同季节水位和颜色变化明显。春季冰雪融化时水量充沛，夏季绿意盎然，秋季彩林倒映最为绚烂，冬季部分海子结冰呈现银装素裹的奇景。",
     "lat": null,
     "lng": null
    }
   ]
