     "desc": "黄龙景区中的一处天然溶洞，位于金沙铺地中段。洞口约宽3米，高约5米，洞内有地下泉水流过。传说唐僧取经归来曾在此洗身，故得名洗身洞。洞内温度恒定，钟乳石形态各异，是黄龙游览线路中的重要节点。",
