     "desc": "位于中国丹霞遗产地附近，全面展示丹霞地貌的地质科学知识和文化遗产价值。馆内陈列有丹霞地貌的模型、岩石标本和科普展板，通过互动展项让游客了解丹霞地貌的形成过程和地质演化历史。博物馆还展示了丹霞地貌区的生态系统和文化遗产，包括道教文化、佛教文化等人文景观。",
     "lat": null,
     "lng": null
