     "desc": "位于澄江市与玉溪市之间，是中国最深的淡水湖泊，最大水深约158米。抚仙湖湖水清澈见底，水质优良，是重要的饮用水源地。湖中有孤山岛等景点，湖岸线曲折，风景优美。抚仙湖与澄江化石地相距不远，共同构成了澄江地区自然与文化相结合的旅游区域。湖区内还有古渔村和彝族文化遗迹，增添了人文气息。",
