     "name": "上海崇明东滩（第二期）",
     "desc": "中国黄渤海候鸟栖息地世界遗产的二期扩展组成部分，位于上海市崇明岛东部。崇明东滩是长江入海口最大的冲积沙洲湿地，面积约2000公顷，是东亚—澳大利西亚迁飞通道上重要的候鸟停歇地和越冬地。东滩湿地有芦苇荡、潮沟和浅滩等多种生境，栖息着黑嘴鸥、大鸨等珍稀鸟类。东滩候鸟观测塔是观赏候鸟迁飞的绝佳位置。",
