     "desc": "位于乐山大佛头部后方山体内，与大佛融为一体。凌云寺始建于唐代，寺内有凌云栈阁和摩崖造像。从凌云寺可俯瞰大佛全景和三江汇流，视野极佳。凌云寺与大佛共同构成了乐山最具标志性的文化景观。",
     "lat": null,
