     "name": "下梅古民居",
     "desc": "武夷山脚下的古村落，位于武夷山市区东南方向。下梅村始建于宋代，明清时期因茶叶贸易而繁荣，是武夷山乌龙茶和红茶的重要集散地。村内保存有大量明清时期的古民居和古巷道，有邹氏家祠、梅氏家祠等建筑。古村落旁的古码头和茶路遗址见证了武夷山茶叶贸易的辉煌历史。",
